import random
import string
from typing import List

# This generator produces valid NUL-terminated textual buffers (without embedded NULs)
# to exercise logging, error formatting, path handling, cpuset parsing, base64 decoding,
# and JSON/mount/spec related code paths. It crafts strings from several families:
# - Human-readable messages (including errno-like and verbosity hints)
# - Paths (absolute, relative, procfs, sockets-like)
# - Known executable names / signals / cpusets / base64 variants
# - JSON snippets (valid and minimal-invalid)
# - SELinux/AppArmor labels and mount options
# - Container IDs and state roots
# The output is bytes suitable for FUZZ_PARAM_STR or FUZZ_PARAM_FILENAME providers.

MAX_LEN = 1024

_words = [
    "alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta",
    "container", "state", "root", "bundle", "rootfs", "cgroup", "scope",
    "warning", "error", "debug", "info", "journal", "syslog", "stderr",
    "mount", "selinux", "apparmor", "seccomp", "namespace", "limit",
    "oom", "memory", "cpu", "cpuset", "pid", "uid", "gid",
]

_base64_alphabet = string.ascii_letters + string.digits + "+/"

_cpuset_samples = [
    "0", "1", "0-3", "0-3,6", "2,4-5", "0-63:2/4",  # include stride-like or extended patterns
]

_signal_names = ["TERM", "SIGTERM", "INT", "KILL", "HUP", "USR1", "USR2", "ALRM", "CHLD"]

_paths = [
    "/var/lib/containers", "/run/containers", "/tmp", ".", "..",
    "self/cmdline", "self/status", "self/limits", "status", "cmdline", "fd/0",
]

_mount_opts = [
    "ro", "rw", "nosuid", "nodev", "noexec", "context=system_u:object_r:container_file_t:s0",
]

_selinux_labels = [
    "unconfined_u:unconfined_r:unconfined_t:s0",
    "system_u:system_r:container_t:s0:c1,c2",
]

_apparmor_profiles = [
    "unconfined", "cri-containerd.apparmor.d", "docker-default",
]

_json_valid_templates = [
    '{"ociVersion":"1.0.2","process":{"args":["/bin/sh","-c","echo hi"]}}',
    '{"process":{"terminal":false,"cwd":"/","args":["echo","ok"]}}',
]

_json_invalid_minimals = ["{", "[", '{"process":', '{"args":[1,', '"unterminated']

# Filename-like generators often benefit from sane basename + random suffix

def _rand_id(r: random.Random, min_len=3, max_len=20) -> str:
    alphabet = string.ascii_lowercase + string.digits + "-_"
    n = r.randint(min_len, max_len)
    s = ''.join(r.choice(alphabet) for _ in range(n))
    return s.strip("-") or "id"


def _rand_words(r: random.Random, nmin=2, nmax=6) -> str:
    n = r.randint(nmin, nmax)
    return ' '.join(r.choice(_words) for _ in range(n))


def _rand_base64(r: random.Random, nmin=4, nmax=120, valid=True) -> str:
    n = r.randint(nmin, nmax)
    s = ''.join(r.choice(_base64_alphabet) for _ in range(n))
    # Optional padding to be more valid
    pad_choice = r.randint(0, 3)
    if valid:
        if n % 4 == 1:
            s += "==="[:3]
        elif n % 4 == 2:
            s += "=="
        elif n % 4 == 3:
            s += "="
    else:
        # introduce slight invalidity sometimes
        if pad_choice == 0:
            s = s + "=" * r.randint(1, 3)
        elif pad_choice == 1 and n > 0:
            s = s[:-1] + "*"  # invalid char
    return s


def _rand_path(r: random.Random) -> str:
    # Build 2-4 components
    comps = []
    if r.random() < 0.6:
        comps.append("/")
    for _ in range(r.randint(1, 4)):
        part_kind = r.random()
        if part_kind < 0.2:
            comps.append(".")
        elif part_kind < 0.3:
            comps.append("..")
        else:
            comps.append(_rand_id(r, 1, 8))
    p = "/".join(c for c in comps if c)
    # Sometimes ensure it maps to proc-ish path used in stubs
    if r.random() < 0.3:
        p = r.choice(["/proc/self/cmdline", "/proc/self/status", "/proc/%d/status" % r.randint(1, 32768)])
    return p


def _rand_cpuset(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(_cpuset_samples)
    # generate e.g., 0-3,6,8-9
    parts: List[str] = []
    base = 0
    for _ in range(r.randint(1, 4)):
        a = r.randint(base, base + r.randint(0, 8))
        if r.random() < 0.6:
            b = r.randint(a, a + r.randint(0, 8))
            if a == b:
                parts.append(str(a))
            else:
                parts.append(f"{a}-{b}")
        else:
            parts.append(str(a))
        base = a + r.randint(0, 4)
    return ",".join(parts)


