        return r.choice(_selinux_labels)
    cats = ",".join(f"c{r.randint(0,1023)}" for _ in range(r.randint(1, 3)))
    return f"system_u:system_r:container_t:s0:{cats}"


def _rand_apparmor(r: random.Random) -> str:
    if r.random() < 0.5:
        return r.choice(_apparmor_profiles)
    return _rand_id(r)


def _rand_mount_options(r: random.Random) -> str:
    opts = set()
    for _ in range(r.randint(1, 4)):
        opts.add(r.choice(_mount_opts))
    return ",".join(sorted(opts))


def _rand_json(r: random.Random) -> str:
    if r.random() < 0.6:
        return r.choice(_json_valid_templates)
    return r.choice(_json_invalid_minimals)


def _pick_family(r: random.Random) -> str:
    families = [
        "message", "path", "procpath", "base64_valid", "base64_maybe_invalid",
        "cpuset", "signal", "execname", "json", "selinux", "apparmor", "mountopts",
        "container_id", "state_root", "suffix_test",
    ]
    return r.choice(families)


def _build_for_family(r: random.Random, fam: str) -> str:
    if fam == "message":
        return f"{_rand_words(r)} {r.randint(0, 1000000)}"
    if fam == "path":
        return _rand_path(r)
    if fam == "procpath":
        return r.choice(_paths)
    if fam == "base64_valid":
        return _rand_base64(r, valid=True)
    if fam == "base64_maybe_invalid":
        return _rand_base64(r, valid=False)
    if fam == "cpuset":
        return _rand_cpuset(r)
    if fam == "signal":
        return r.choice(_signal_names)
    if fam == "execname":
        return r.choice(["sh", "bash", "echo", "true", "false", _rand_id(r)])
    if fam == "json":
        return _rand_json(r)
    if fam == "selinux":
        return _rand_selinux_label(r)
    if fam == "apparmor":
        return _rand_apparmor(r)
    if fam == "mountopts":
        return _rand_mount_options(r)
    if fam == "container_id":
        return _rand_id(r, 3, 40)
    if fam == "state_root":
        base = r.choice(["/run/containers", "/var/lib/containers", "/tmp", "/run/user/%d" % r.randint(0, 65535)])
        return base
    if fam == "suffix_test":
        base = _rand_id(r, 3, 12)
        suf = r.choice([".json", ".log", ".conf", ".mount", ".txt", "/end"]) \
              if r.random() < 0.8 else _rand_id(r, 1, 4)
        joiner = r.choice(["", "-", "_", "/"]) if not suf.startswith("/") else ""
        return base + joiner + suf
    return _rand_words(r)


def _clip(s: str) -> str:
    if len(s) > MAX_LEN:
        return s[:MAX_LEN]
    return s


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # sometimes concatenate multiple families to create richer inputs
    parts: List[str] = []
    count = 1 if r.random() < 0.5 else r.randint(2, 4)
    used_fams = set()
    for _ in range(count):
        fam = _pick_family(r)
        # avoid repeating same family too often
        for _retry in range(3):
            if fam in used_fams and r.random() < 0.7:
                fam = _pick_family(r)
            else:
                break
        used_fams.add(fam)
        parts.append(_build_for_family(r, fam))
    sep = r.choice([" ", "\n", "/", ":", ","]) if len(parts) > 1 else ""
    out = sep.join(parts)
    out = _clip(out)
    # Ensure no embedded NUL and non-empty
    out = out.replace("\x00", "?")
    if not out:
        out = "x"
    return out.encode("utf-8", errors="replace")

import os
import random
import string
from typing import List, Tuple

# Data type: filesystem path
# We must return bytes that the fuzz harness will use for both FUZZ_PARAM_STR and
# FUZZ_PARAM_FILENAME. Therefore, prioritize generating NUL-terminated printable
# path-like content that maps to real files/dirs when used as filenames, while
# also producing interesting variations (absolute/relative, with . and .., with
# trailing slashes, symlinks, FIFOs, sockets, dirs, regular files, empty files,
# and files with data). The harness writes to and reads from paths in the current
# working directory; we avoid any external I/O beyond constructing the bytes.
#
# Strategy
# - Create a small virtual path namespace under a relative base like fuzzfs/.
# - Compose paths to existing entries we describe in-text so the fuzzer runtime
#   can pre-create them if it mirrors the input buffer onto disk. However, the
#   stub expects FUZZ_PARAM_FILENAME to point to an existing file with random
#   data. Since we cannot create files here, we instead generate a self-contained
#   byte buffer that contains a mini tar-like multi-file payload is not allowed.
#   So, we choose to generate a single path string. To maximize success, we
#   return simple relative names most of the time (the harness typically ensures
#   a file exists at the provided filename). We vary suffixes to trigger
#   different code paths (directories, symlinks, etc.) by using common patterns
#   such as trailing slash, dot, and dot-dot components.
# - Keep size under 4096 bytes.
# - Ensure NUL-termination is handled by the harness, so we just return bytes of
#   the path string.

SAFE_CHARS = string.ascii_letters + string.digits + "-._"

def _rand_name(rng: random.Random, min_len: int = 3, max_len: int = 10) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(SAFE_CHARS) for _ in range(n))

def _choose_components(rng: random.Random) -> List[str]:
    comps: List[str] = []
    depth = rng.randint(0, 4)
    for _ in range(depth):
        kind = rng.choices(
            population=["norm", "dot", "dotdot", "hidden"],
            weights=[70, 10, 10, 10],
            k=1,
        )[0]
        if kind == "norm":
            comps.append(_rand_name(rng))
        elif kind == "dot":
            comps.append(".")
        elif kind == "dotdot":
            comps.append("..")
        else:
            comps.append("." + _rand_name(rng))
    # Ensure at least one terminal filename component
    terminal_kind = rng.choices(["file", "tmp", "json", "txt", "sock", "fifo", "dirlike"], [40, 5, 15, 15, 5, 5, 15])[0]
    base = _rand_name(rng)
    if terminal_kind == "file":
        name = base
    elif terminal_kind == "tmp":
        name = base + ".tmp"
    elif terminal_kind == "json":
        name = base + ".json"
    elif terminal_kind == "txt":
        name = base + ".txt"
    elif terminal_kind == "sock":
        name = base + ".sock"
    elif terminal_kind == "fifo":
        name = base + ".fifo"
    else:
        name = base  # will add trailing slash later to hint directory
    comps.append(name)
    return comps

def _maybe_prefix(rng: random.Random) -> str:
    # Choose absolute, relative, or cwd-prefixed
    choice = rng.choices(["rel", "abs", "cwd"], [60, 25, 15])[0]
    if choice == "rel":
        return ""
    if choice == "abs":
        # Use a simple absolute base to avoid privileged dirs
        bases = ["/tmp", "/var/tmp", "/dev/shm", "/"]
        return rng.choice(bases)
    return "."  # cwd

def _decorate(path: str, rng: random.Random) -> str:
    # Possibly add leading ./ or redundant slashes, or trailing slashes
    # and also embed a few redundant separators.
    parts = path.split('/')
    # Collapse accidental empties later; we intentionally allow "" to get //
    def jitter_segment(seg: str) -> str:
        if seg in ("", ".", ".."):
            return seg
        # Occasionally add characters that are valid in filenames
        if rng.random() < 0.15:
            seg = seg + rng.choice(["-", "_", "."]) * rng.randint(1, 2)
        return seg
    parts = [jitter_segment(p) for p in parts]
    # Randomly insert empty segments to create //
    if rng.random() < 0.2:
        insert_pos = rng.randrange(1, len(parts)+1)
        parts.insert(insert_pos, "")
    decorated = "/".join(parts)
    # Optional leading ./
    if rng.random() < 0.25 and not decorated.startswith('/'):
        decorated = "./" + decorated
    # Optional trailing slashes (help consume_trailing_slashes)
    if rng.random() < 0.4:
        decorated = decorated + "/" * rng.randint(1, 3)
    return decorated

def _build_path(rng: random.Random) -> str:
    prefix = _maybe_prefix(rng)
    comps = _choose_components(rng)
    # If prefix is absolute and equals "/", avoid double slash later
    if prefix == "" or prefix == ".":
        base = prefix
    else:
        base = prefix.rstrip('/')
    core = "/".join(comps)
    if base == "":
        path = core
    elif base == ".":
        path = core if rng.random() < 0.5 else f"./{core}"
    elif base == "/":
        path = f"/{core}"
    else:
        path = f"{base}/{core}"
    path = _decorate(path, rng)
    # Bound length
    if len(path) > 4000:
        path = path[-4000:]
        if not path:
            path = _rand_name(rng)
    return path

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose among several path families to exercise different APIs
    family = rng.choices(
        [
            "simple_file",           # likely existing fuzz file path
            "dir_like",              # triggers directory behavior
            "symlink_like",          # name suggests symlink target
            "procfs_like",           # /proc style paths
            "socket_like",           # .sock suffix
            "fifo_like",             # .fifo suffix
            "json_cfg",              # .json for config loaders
        ],
        [40, 10, 10, 5, 10, 10, 15]
    )[0]

    path = _build_path(rng)

    # Post-adjust by family
    if family == "dir_like":
        if not path.endswith('/'):
            path += '/' * rng.randint(1, 2)
    elif family == "symlink_like":
        # Common names used for links
        base = _rand_name(rng)
        path = _decorate(os.path.join(os.path.dirname(path) or '.', base + "_link"), rng)
    elif family == "procfs_like":
        # Create a plausible /proc path
        pid = rng.randint(1, 32768)
        tail = rng.choice(["cmdline", "maps", "status", "fd/0", "fd/1", "cwd"]).strip('/')
        path = f"/proc/{pid}/{tail}"
        if rng.random() < 0.3:
            path += '/'  # trailing slash to test normalization
    elif family == "socket_like":
        if not path.endswith('.sock'):
            path = path.rstrip('/') + '.sock'
    elif family == "fifo_like":
        if not path.endswith('.fifo'):
            path = path.rstrip('/') + '.fifo'
    elif family == "json_cfg":
        if not path.endswith('.json'):
            path = path.rstrip('/') + '.json'

    # Ensure non-empty and within limit
    if not path:
        path = _rand_name(rng)
    if len(path) > 4096:
        path = path[:4096]

    return path.encode('utf-8')
